insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('google-ai-news-and-product-updates', 'rss', 'https://blog.google/innovation-and-ai/technology/ai/rss/', 'Google', 'AI news and product updates', 'en', 'Google is the technology company behind Search, Android and the Gemini AI models. This is its AI section on the official company blog: model and product launches such as Gemini app features, research collaborations on data and science, AI safety and societal impact pieces, developer tools like Antigravity, and roundups of the month''s AI announcements. It does not cover Google''s non AI product lines such as hardware or ads.', 6.2, null, null, '["New experts join Google''s AI & Economy team","Co-creating the future of fashion with Google","Making global data easier to explore"]')
