insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('sam-altman-personal-blog', 'rss', 'https://blog.samaltman.com/posts.atom', 'Sam Altman', 'Personal blog', 'en', 'Sam Altman is the chief executive of OpenAI. This is the feed of his personal blog: essays on AI progress and the path toward superintelligence, product moments such as Sora 2 and GPT-4o, notes on Helion fusion, and personal reflections on founders and friends. It is opinion and personal writing, not official OpenAI product announcements.', 1.2, null, null, '["Reflections","Sora 2","What I Wish Someone Had Told Me"]')
