insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('bolt-new-product-and-customer-stories', 'website', 'https://bolt.new/blog', 'Bolt.new', 'Product and customer stories', 'en', 'Bolt.new is an AI powered web app builder. This is its blog: customer stories about people and companies building products on Bolt, feature explainers like Bolt Forge, and how to guides comparing AI, low code and no code app building. It does not cover general AI industry news unrelated to Bolt''s own product.', 12.8, null, null, '["Writers deserve receipts. A filmmaker built them on Bolt.new.","Flag football is having a moment. FlagStat is keeping score","What is Bolt Forge?"]')
