insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('hugging-face-community-ml-research-blog', 'rss', 'https://huggingface.co/blog/feed.xml', 'Hugging Face', 'Community ML research blog', 'en', 'Hugging Face is the open platform and company behind the Transformers library and model hub. This is its blog feed: mostly community authored posts on training and fine tuning techniques, new open models and benchmarks, agent and coding tools, and Gradio app tutorials. Posts come from Hugging Face staff and outside researchers publishing through the platform, not just the company itself.', 4.8, null, null, '["Your Agent Aced the Task. Will It Do It Again?","Async GRPO with LoRA across HF Jobs: a bucket, a proxy, and no NCCL","Rebuilding AUTOMATIC1111 with Gradio Workflow"]')
