insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('techcrunch-ai-industry-news', 'rss', 'https://techcrunch.com/category/artificial-intelligence/feed/', 'TechCrunch', 'AI industry news', 'en', 'TechCrunch is a technology news outlet covering startups and the tech industry. This is its artificial intelligence section: model and product launches from labs like Anthropic and OpenAI, funding rounds for AI startups, safety incidents and security research, and analysis of AI company strategy. It does not cover TechCrunch''s non AI beats such as fintech or transportation except where AI is the story.', 267.7, null, null, '["A startup that builds other startups raised $100M, and is all-in on physical AI","Anthropic is operating a lab that conducts biology experiments","AI hallucination nearly triggers US military operation"]')
