insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('techcrunch-startup-and-technology-news', 'rss', 'https://techcrunch.com/feed/', 'TechCrunch', 'Startup and technology news', 'en', 'TechCrunch is a technology news outlet covering startups and the broader tech industry. This is its site wide feed: funding rounds across sectors, product launches, company leadership changes, and consumer technology stories, alongside a heavy share of AI coverage on labs, models and agents. It does not filter to any single beat, it mixes AI with fintech, mobility, gadgets and general startup news.', 339.8, null, null, '["A startup that builds other startups raised $100M, and is all-in on physical AI","Anthropic is operating a lab that conducts biology experiments","AI hallucination nearly triggers US military operation"]')
