insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('mundo-deportivo-transfer-market', 'rss', 'https://www.mundodeportivo.com/feed/rss/futbol/fichajes', 'Mundo Deportivo', 'Transfer market', 'es', 'Mundo Deportivo is a Barcelona based sports daily. This is its transfer market feed: player moves and rumours across Spanish and international football, such as Messi signing a coach for his club Eldense and James Rodriguez returning to Colombian football, plus coaching changes and contract renewals. It does not cover match results or on field action, it stays focused on signings and transfer speculation.', 14.4, null, null, '["Messi signs his first coach for Eldense","James Rodriguez, the end of the road","The Premier League champion who could change teams"]')
