insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('sport-fc-barcelona-club-news', 'website', 'https://www.sport.es/es/barca/', 'Sport', 'FC Barcelona club news', 'es', 'Sport is a Barcelona-based sports daily. This is its FC Barcelona hub: first-team news and player quotes, the women''s team in Liga F, and La Masia academy prospects, alongside transfer talk and squad updates. Recent items cover Raphinha discussing the Ballon d''Or race, a newly chosen artist for the Clasico shirt, and a Liga F match report against Alaves. It spans every part of the club, not a single beat such as transfers or match results alone.', null, null, null, '["Raphinha: It''s unfair that Pedri and I aren''t up for the Ballon d''Or","Barca already has an artist for the Clasico shirt","The Camp Nou that wasn''t in the plans"]')
on conflict (id) do update set name = excluded.name, focus = excluded.focus, lang = excluded.lang, description = excluded.description, items_per_week = excluded.items_per_week, posts_per_day = excluded.posts_per_day, followers = excluded.followers, recent_titles = excluded.recent_titles;

