insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('the-verge-ai-news', 'rss', 'https://www.theverge.com/rss/ai-artificial-intelligence/index.xml', 'The Verge', 'AI news', 'en', 'The Verge is a technology and culture publication founded in 2011. This is its AI section: model and product launches, legal disputes such as the New York Times case against OpenAI and Microsoft, government moves like a proposed California AI kill switch, and safety debates including a hack on OpenAI carried out with Claude. It also covers how Hollywood is reacting to AI. General Verge coverage outside AI sits elsewhere on the site.', 54, null, null, '["OpenAI and Microsoft knew they were starting a doom loop for the web","Virginia governor creates an AI task force and moves to restrain data centers","Gavin Newsom is pushing for an AI kill switch"]')
