insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('wired-ai-news-and-policy', 'rss', 'https://www.wired.com/feed/tag/ai/latest/rss', 'Wired', 'AI news and policy', 'en', 'Wired is a technology and culture magazine owned by Conde Nast. This is its AI feed: policy and safety stories such as proposals to slow AI development, PAC spending tied to AI labs in a Senate race, and debate over an industry-wide AI pause, alongside pieces on AI bioweapon risk and an AI clone of teachers from a revived Napster. It leans toward AI''s political and safety angles over product reviews.', 68.2, null, null, '["Here''s How an AI Slowdown Could Actually Be Enforced","AI PACs Have Dumped Nearly $1 Million Into an Obscure Senate Race","If the AI Industry Followed Its Own Research, It Might Have Paused Already"]')
