insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('marca-fc-barcelona-news', 'rss', 'https://www.marca.com/rss/googlenews/futbol/barcelona.xml', 'Marca', 'FC Barcelona news', 'es', 'Marca is a Madrid-based sports daily. This is its automated Barcelona news feed: match previews and reports, press-conference quotes from Hansi Flick and opposing coaches, injury updates such as goalkeeper Joan Garcia''s knee problem, and player interviews touching on the Ballon d''Or race. It occasionally pulls in rival-club angles. It covers the club broadly, not one single beat such as transfers alone.', 104.5, null, null, '["Baena: Lamine is the best in the world, I see him training and doing things no teammate does","Sevilla - Barca: the unbeaten side go for a clean sweep before the break","Raphinha: I don''t understand what Atletico did to Julian"]')
