insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('fc-barcelona-confirmed-transfers', 'website', 'https://www.fcbarcelona.com/en/transfer-market', 'FC Barcelona', 'Confirmed transfers', 'en', 'FC Barcelona is the football and multi-sport club based in Barcelona. This is the official site''s transfer market page: confirmed first-team signings such as Rodri, Gabriel Jesus, Dominik Livakovic and Joao Cancelo, and departures such as Ferran Torres, Ansu Fati and several La Masia graduates sent on transfer or loan. It lists only finalised moves, not rumours or ongoing negotiations.', 3.8, null, null, '["Gabriel Jesus signs for Barca","Rodri signs for Barca","Cancelo back with Barca"]')
