insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('supermemory-company-engineering-blog', 'rss', 'https://supermemory.ai/blog/rss.xml', 'Supermemory', 'Company engineering blog', 'en', 'Supermemory is a startup building a memory layer for AI agents and applications. This is its engineering blog: product announcements such as a new Context Cloud pricing tier and a Dynamic Dreaming feature, technical write-ups on search precision and retrieval costs, and posts about integrations with coding agents and Claude Code. It is written by the founding team, mixing engineering detail with product news.', 0.3, null, null, '["An update to supermemory","Scaling Conversations: How Adapta Grew Usage Without Losing Context","How Chatarmin Ditched RAG and Went Memory-Only with Supermemory"]')
on conflict (id) do update set name = excluded.name, focus = excluded.focus, lang = excluded.lang, description = excluded.description, items_per_week = excluded.items_per_week, posts_per_day = excluded.posts_per_day, followers = excluded.followers, recent_titles = excluded.recent_titles;

insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('openrouter-company-blog', 'rss', 'https://openrouter.ai/blog/feed.xml', 'OpenRouter', 'Company blog', 'en', 'OpenRouter is a unified API and marketplace for large language models. This is its blog: tutorials for building tool-calling agents and using text-to-speech or image endpoints, insight pieces comparing model pricing such as DeepSeek V4''s vision support, case studies like Descript''s model-evaluation workflow, and announcements such as in-region data routing. It does not cover unrelated consumer technology news.', 4.4, null, null, '["Image Generation Models Compared: Cost, Edit, Quality","Build a Reliable Tool-Calling Agent Loop on OpenRouter","Does DeepSeek V4 Have Vision?"]')
