insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('sarthak-rastogi-ai-agent-engineering', 'rss', 'https://sarthakai.substack.com/feed', 'Sarthak Rastogi', 'AI agent engineering', 'en', 'Sarthak Rastogi is an AI engineer writing the newsletter AI Agent Engineering. This is his main stream: tutorials with code for making agents observable and production-ready, essays on harness, graph and loop engineering, comparisons of retrieval-augmented generation against fine-tuning, and guides to chunking strategies. It is practical, code-backed writing about building and deploying AI agents.', 0.3, null, null, '["Making AI Agents Observable, Monitorable, and Production-Ready","Harness, Graph, and Loop Engineering","Making AI Agents Production-Ready with CI/CD Pipelines"]')
on conflict (id) do update set name = excluded.name, focus = excluded.focus, lang = excluded.lang, description = excluded.description, items_per_week = excluded.items_per_week, posts_per_day = excluded.posts_per_day, followers = excluded.followers, recent_titles = excluded.recent_titles;

insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('ai-engineering-insider-ai-interview-prep-guides', 'rss', 'https://aiengineeringinsider.substack.com/feed', 'AI Engineering Insider', 'AI interview prep guides', 'en', 'AI Engineering Insider is a newsletter aimed at AI engineers preparing for technical interviews. This is its main stream: long guides on reinforcement learning from human feedback, agentic evaluation systems, distributed LLM inference and model compression, each paired with interview questions on the same topic. Nearly every post doubles as an interview-prep handbook rather than general AI news.', 2.9, null, null, '["Complete Roadmap: Reinforcement Learning from Human Feedback (RLHF)","Agentic Evals System Design using DeepEval, Ragas, Langsmith, and Trulens","Everything You Need to Prepare for a Hugging Face Interview"]')
on conflict (id) do update set name = excluded.name, focus = excluded.focus, lang = excluded.lang, description = excluded.description, items_per_week = excluded.items_per_week, posts_per_day = excluded.posts_per_day, followers = excluded.followers, recent_titles = excluded.recent_titles;

insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('hugo-bowne-anderson-ai-engineering-podcast', 'rss', 'https://api.substack.com/feed/podcast/2632531.rss', 'Hugo Bowne-Anderson', 'AI engineering podcast', 'en', 'Vanishing Gradients is a podcast hosted by Hugo Bowne-Anderson. This is its main feed: long-form interviews with people building AI systems, covering coding agents, AI evals, healthcare AI deployments, and durable agent architecture, with guests including Hamel Husain and Sebastian Raschka. Episodes lean toward the practical side of shipping AI products rather than research theory alone.', 0.5, null, null, '["How to Build a Coding Agent with Nico (Amp Code)","The Rise of the AI Scientist","If Developers Build on Chinese Open-Weight Models, Who Leads AI?"]')
on conflict (id) do update set name = excluded.name, focus = excluded.focus, lang = excluded.lang, description = excluded.description, items_per_week = excluded.items_per_week, posts_per_day = excluded.posts_per_day, followers = excluded.followers, recent_titles = excluded.recent_titles;

insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('nathan-lambert-ai-research-podcast', 'rss', 'https://api.substack.com/feed/podcast/48206.rss', 'Nathan Lambert', 'AI research podcast', 'en', 'Interconnects is a newsletter and podcast written by Nathan Lambert, a former Allen Institute for AI researcher. This is its main feed: audio essays and interviews on model releases such as Kimi K3 and GLM-5.2, the open versus closed AI model debate, and post-training techniques, plus commentary on AI safety incidents. It leans toward technical analysis of frontier model training, not general AI business news.', 0.8, null, null, '["One resignation turned the embers of AI fear into a wildfire","When will average people feel AI''s impact?","I wrote an AI textbook, how long until AI can do it better?"]')
on conflict (id) do update set name = excluded.name, focus = excluded.focus, lang = excluded.lang, description = excluded.description, items_per_week = excluded.items_per_week, posts_per_day = excluded.posts_per_day, followers = excluded.followers, recent_titles = excluded.recent_titles;

insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('builder-io-company-blog', 'rss', 'https://www.builder.io/blog/feed/atom', 'Builder.io', 'Company blog', 'en', 'Builder.io is a company building AI-native development and content tools. This is its blog: product announcements such as Agent-Native Analytics and a Figma-style design tool, essays on why coding agents outperform typical AI tools, and comparison guides covering alternatives to Gmail, PowerPoint and Google Forms. It focuses on building software with AI agents rather than general programming tutorials.', 2.1, null, null, '["The Real Reason Coding Agents Get More Done","How to De-Slop an AI-Generated Codebase","Introducing Agent Native Analytics"]')
