insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('llm-gateway-company-blog', 'website', 'https://llmgateway.io/blog', 'LLM Gateway', 'Company blog', 'en', 'LLM Gateway is a company providing a unified API for routing requests across AI models. This is its blog: tutorials on model routing, caching and cost tracking, comparisons of AI coding plans and gateway competitors such as Vercel AI Gateway, Helicone and Portkey, news on model releases like Kimi K3 and GLM-5.2, and compliance guidance on GDPR and data retention. It mixes practical guides with company product announcements. It does not cover general consumer AI news.', 3.9, null, null, '["Cheap vs Flagship AI Models: $0.10 vs $198","How to Get Your LLM API Listed on an AI Gateway","How LLM Routing Picks a Provider: A Carrier''s Guide"]')
