insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('microsoft-microsoft-365-and-copilot-news', 'rss', 'https://www.microsoft.com/en-us/microsoft-365/blog/feed/', 'Microsoft', 'Microsoft 365 and Copilot news', 'en', 'Microsoft is the technology company behind Windows, Office and Azure. This is its Microsoft 365 blog: Copilot feature launches such as Microsoft Scout and new Work IQ APIs, enterprise and government product tiers including Microsoft 365 G7, conference announcements for events like ESPC 2026, and updates on Copilot adoption figures and pricing for small businesses. It focuses on Microsoft 365 and Copilot specifically, not Windows, Xbox or other Microsoft product lines.', 0.6, null, null, '["Introducing Microsoft 365 G7: Intelligence + Trust for the mission ahead","ESPC 2026 is coming to Amsterdam","Build apps in Copilot Cowork and Copilot Studio"]')
