insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('microsoft-ai-ai-model-announcements', 'website', 'https://microsoft.ai/blog/', 'Microsoft AI', 'AI model announcements', 'en', 'Microsoft AI is Microsoft''s product and research group behind the MAI family of models. This is its blog: launches of MAI models such as MAI-Image, MAI-Voice, MAI-Transcribe and MAI-Thinking, claims about their cost and quality against rivals on Arena leaderboards, and posts on responsible AI practices and Copilot Health features. It does not cover Microsoft''s wider corporate news outside this model line.', null, null, null, '["Humanist AI in practice: A public consultation on our Code of Conduct for MAI Models","Pushing the quality-cost frontier with MAI-Image-2.6","MAI-Transcribe-2 is the fastest, most accurate and cheapest speech recognition model in the world"]')
