insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('productdirs-daily-ai-tool-launches', 'website', 'https://productdirs.com/blog', 'ProductDirs', 'Daily AI tool launches', 'en', 'ProductDirs runs an AI tools launch directory and product discovery platform. This is its blog: short roundup posts naming the AI tools that launched on a given day, spanning categories such as coding assistants, marketing tools and productivity apps, each with a one line description and a link to its listing. It does not review or rank the tools in depth; entries are launch summaries rather than analysis.', 2.8, null, null, '["Yesterday''s Top Launches: 5 Tools from September 16, 2026","Yesterday''s Top Launches: 5 Tools from September 15, 2026","Yesterday''s Top Launches: 5 Tools from September 14, 2026"]')
