insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('microsoft-cowork-feature-changelog', 'website', 'https://learn.microsoft.com/en-us/microsoft-365/copilot/cowork/whats-new', 'Microsoft', 'Cowork feature changelog', 'en', 'Microsoft is the company behind Microsoft 365 Copilot Cowork. This is its official changelog page: dated entries listing new features and enhancements, including new model options such as Claude Fable and GPT 6 Astra, plugin and skill management, event driven automations, mobile app support and usage based billing changes. It does not cover other Copilot products outside the Cowork agent experience.', 1.1, null, null, '["App skill (Frontier)","Claude Fable 5.1 model","GPT 6 Astra model"]')
