insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('ars-technica-ai-news', 'rss', 'https://arstechnica.com/ai/feed', 'Ars Technica', 'AI news', 'en', 'Ars Technica is a technology news and analysis publication founded in 1998. This is its AI section feed: coverage of AI safety incidents and misuse, government and military AI deployments, model releases from major labs, AI hardware and infrastructure, and disputes between AI companies and content publishers. It does not cover Ars Technica''s other beats such as gaming, space or general consumer tech.', 26, null, null, '["AI hallucination of Chinese nuclear components almost led to US military attack","FAA tees up $875M AI tool to help manage air traffic congestion","US government website used Chinese model the FBI called \"malicious\""]')
on conflict (id) do update set name = excluded.name, focus = excluded.focus, lang = excluded.lang, description = excluded.description, items_per_week = excluded.items_per_week, posts_per_day = excluded.posts_per_day, followers = excluded.followers, recent_titles = excluded.recent_titles;

insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('jack-clark-ai-newsletter', 'rss', 'https://importai.substack.com/feed', 'Jack Clark', 'AI newsletter', 'en', 'Jack Clark is a co-founder of Anthropic who writes Import AI in a personal capacity. This is his newsletter: analysis of new AI research papers, frontier model releases and reasoning capabilities, self improving AI and safety risks, and commentary on AI policy fights over export controls and open model access. It focuses on frontier research and its implications rather than day to day product news.', 1, null, null, '["Import AI 472: DeepMind''s cheating math agents; populist AI policies; and Forethought theorizes a nightwatchman","Import AI 471: Why Hugging Face worries me; space mining; Five Eyes on AI","Import AI 470: No rights for machines; automating environment generation with SPADE; and building better GPU kernels with Hawkeye"]')
