values ('nathan-lambert-open-model-analysis', 'rss', 'https://www.interconnects.ai/feed', 'Nathan Lambert', 'Open model analysis', 'en', 'Nathan Lambert is an AI researcher who writes Interconnects. This is his newsletter: deep analysis of open weight model releases such as GLM, Kimi and Motif, reinforcement learning and post training methods, and commentary on the balance of power between open and closed AI labs. It also covers his own post training textbook and reading lists rather than general AI news.', 1.4, null, null, '["Open-Source AI & Open Models Reading List","One resignation turned the embers of AI fear into a wildfire","When will average people feel AI''s impact?"]')
on conflict (id) do update set name = excluded.name, focus = excluded.focus, lang = excluded.lang, description = excluded.description, items_per_week = excluded.items_per_week, posts_per_day = excluded.posts_per_day, followers = excluded.followers, recent_titles = excluded.recent_titles;

insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('sebastian-raschka-llm-research-explainer', 'rss', 'https://magazine.sebastianraschka.com/feed', 'Sebastian Raschka', 'LLM research explainer', 'en', 'Sebastian Raschka is a machine learning researcher and educator. This is his newsletter Ahead of AI: technical explainers on large language model architectures, reasoning and inference time scaling, and how coding agents are built, plus curated roundups of notable research papers each year. It focuses on how these systems work rather than on company or product announcements.', 0.4, null, null, '["GPT-6 Astra, Looped Transformers, and Hidden Reasoning","How Claude Watermarks AI-Generated Text","Building an AI Text Detector From Scratch"]')
on conflict (id) do update set name = excluded.name, focus = excluded.focus, lang = excluded.lang, description = excluded.description, items_per_week = excluded.items_per_week, posts_per_day = excluded.posts_per_day, followers = excluded.followers, recent_titles = excluded.recent_titles;

insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('alex-volkov-weekly-ai-news-podcast', 'rss', 'https://sub.thursdai.news/feed', 'Alex Volkov', 'Weekly AI news podcast', 'en', 'Alex Volkov is an AI evangelist at Weights and Biases who hosts ThursdAI. This is his newsletter and podcast: roundups of frontier model releases from OpenAI, Google, Meta and Chinese labs, open weights developments, and interviews with guests from AI companies and research teams. It covers the past week''s biggest AI stories broadly rather than any single company or product.', 1.2, null, null, '["ThursdAI - Sep 17 - TypeSafe''s Jev is a ChatGPT moment for decisions, Pace the Frontier splits the labs & more","OpenAI solves Navier-Stokes, Meta''s Muse a free AI agent that''s really good, DeepSeek V4.1 shrinks KV cache, and one doomer post causes OpenAI to consider pausing training + more AI news","Welcome to AGI - our GPT-6 deep coverage, vibe check and demoes - part 2 of this insane week"]')
