insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('nvidia-corporate-news', 'rss', 'https://blogs.nvidia.com/feed/', 'NVIDIA', 'Corporate news', 'en', 'NVIDIA is the chipmaker whose GPUs power much of modern AI. This is its blog: product and partnership announcements for AI factories and data centers, physical AI and robotics deployments, gaming and GeForce NOW updates, and appearances by executives such as CEO Jensen Huang at industry events. It spans NVIDIA''s full business rather than only its AI research.', 7.6, null, null, '["Cute Critters Come to the Cloud: ''Aniimo'' Launches on GeForce NOW","NVIDIA Vera Rubin NVL72 Delivers Leading Performance in MLPerf Inference v6.1 Debut","Emerald AI, Google and NVIDIA Launch Alliance to Advance Flexible AI Data Centers"]')
