insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('the-decoder-ai-industry-news', 'rss', 'https://the-decoder.com/feed/', 'The Decoder', 'AI industry news', 'en', 'The Decoder is an independent AI news site covering the industry as a whole. This is its main feed: model and product launches from OpenAI, Anthropic and Google DeepMind, safety and policy moves such as executive orders and expert warning letters, research claims like progress on hard math problems, and stories about AI''s effect on copyright and labor. It spans many companies rather than focusing on any single lab.', 72.5, null, null, '["California Governor Newsom signs executive order demanding \"kill switch\" for AI models","Security researchers used Anthropic''s Claude to hack OpenAI''s internal systems in under 72 hours","AI training built on fair use looks shaky when the companies'' own people call it \"astonishing theft\""]')
