insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-alibaba_qwen', 'x_account', 'https://x.com/Alibaba_Qwen', 'Qwen', 'Alibaba''s Qwen open models', 'en', 'Qwen is Alibaba''s open model family. This is their X account: releases such as Qwen Intelligence with its mobile agents, Qwen-Audio-3.1 and Qwen-Image-2.1, benchmark and arena rankings, and thanks to partners like Intel, SGLang and Hugging Face for day-zero support. Many posts are short follow-ups with a chart or a link. It does not cover Alibaba''s business or pricing.', null, 4.2, 291692, '["Benchmark suite: https://t.co/aYhcCvwv82","Performance of Mobile Creative Agent: https://t.co/vZcKCFRkU5","Performance of Mobile-Use Agent: https://t.co/yYFYe3jjIb"]')
