insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-lovable', 'x_account', 'https://x.com/Lovable', 'Lovable', 'AI app builder product updates', 'en', 'Lovable is a startup whose product builds software from a written prompt. This is their X account: which models power Lovable builds (Claude Opus 5.5, GPT-6 Sol) with benchmark comparisons, new features like adding AI to built apps, a free chat product, and community programs such as the SheBuilds hackathon and a Contra prize challenge. It does not post about funding or the wider AI industry.', null, 4.7, 157119, '["We did it. And it''s free. Chat with Lovable now. https://t.co/6yYVuzftgE https://t.co/ibVXR4DkCY","Read the guidelines and join the challenge: https://t.co/ZHBJ15P79q","Freelancers and agencies who build with Lovable: @contra just handed you free Lovable Pro and a chan"]')
