insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-composio', 'x_account', 'https://x.com/composio', 'Composio', 'agent tool integrations, model comparisons', 'en', 'Composio is a startup that connects AI agents to outside apps through integrations and MCP. This is their X account: threads that test named models (GPT-6 Astra, Opus 5.5, Sol, Pareto, DeepSeek, GLM) on agent tasks with cost and time numbers, integration count updates, and how to connect tools like Jev to Claude, ChatGPT and Codex. It does not cover funding news or models outside the agent-tooling angle.', null, 1.5, 24561, '["Models struggled with vague, multi-step tasks like “Can you sync the support tickets?” That required","One takeaway: models that completed the same number of tasks could cost very different amounts.\n\nPar","How long did the models take to complete the tasks?\n\nSol was the fastest model, averaging 110 second"]')
