insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-youdotcom', 'x_account', 'https://x.com/youdotcom', 'You.com', 'web search APIs for agents', 'en', 'You.com sells web search APIs for AI applications. This is their X account: the Knowledge launch that adds licensed real-time data to search results, benchmarks such as VerticalRTK against other search APIs, reranking experiments with named models, workshops, and a partnership with Coinbase on trading agents. Posts are developer threads with numbers and links. It is not a consumer product feed and does not cover the big model labs beyond the models it tests.', null, 3.1, 24051, '["We''re walking through the whole build in a live workshop: the architecture, how the reranking step d","3x fewer tokens. 84% accuracy on the Vertical RTK benchmark.\n\nThat’s what we got using Jev through @","Benchmark, harness and the full write-up.\n\nhttps://t.co/1kDQdpWNVr"]')
