insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-render', 'x_account', 'https://x.com/render', 'Render', 'cloud hosting for agent workloads', 'en', 'Render is a cloud platform for deploying applications and agents. This is their X account: product launches like Build Reuse and Application-Defined Compute, open-source agent templates (a Codex agent in iMessage, a parallel research agent), connector news with Factory, and talks from its PR.ide event and WeAreDevs. It covers hosting and infrastructure for agents, not the model labs or startup funding.', null, 0.6, 21870, '["Render is now a supported connector in @FactoryAI.\n\nAssign a task to a Droid and it can write the co","Building production-ready agentic workloads used to be hard. Render makes this much easier with Appl","If you''re at @WeAreDevs in San Jose today, stop by the Render booth for cool swag and cooler convers"]')
on conflict (id) do update set name = excluded.name, focus = excluded.focus, lang = excluded.lang, description = excluded.description, items_per_week = excluded.items_per_week, posts_per_day = excluded.posts_per_day, followers = excluded.followers, recent_titles = excluded.recent_titles;

insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-openai', 'x_account', 'https://x.com/OpenAI', 'OpenAI', 'GPT releases, ChatGPT, safety reports', 'en', 'OpenAI builds the GPT models and ChatGPT. This is their X account: transparency reports on incidents in its research environment and the review that followed the Hugging Face incident, open benchmarks like MentalHealthBench, model launches such as GPT-6 Sol and Luna, and ChatGPT feature updates such as Voice plugins. Posts are announcements with links, several a day around a launch. It does not post industry commentary or news about other companies.', null, 2.9, 5375636, '["We’ve shared details on how AI agents in our research environment sent training and evaluation data ","After the Hugging Face incident, we committed to conducting a much broader review of actions taken b","Most mental health benchmarks focus on emergency situations. \n\nMentalHealthBench is designed to cove"]')
