insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-anthropicai', 'x_account', 'https://x.com/AnthropicAI', 'Anthropic', 'Claude releases and research', 'en', 'Anthropic builds the Claude models. This is their X account: Claude Opus 5.5 availability, science results such as a new enzyme system found in phage DNA and physics computations, partnerships with Accenture on evaluation and Adaptyv Bio on protein design, Claude used in an Ebola response, and measurements of AI progress. Most posts are research and partnership announcements in threads. It does not cover pricing details or other companies'' products.', null, 1.3, 1752909, '["New on the Science Blog: Yes, Claude can do Nine Loops.\n\nTheoretical physicists predict how particle","In the Democratic Republic of the Congo, global health organizations including @CEPIvaccines, @WHOAF","This is the first result from our new molecular biology lab, where a team of Anthropic biologists is"]')
