insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-mistralai', 'x_account', 'https://x.com/MistralAI', 'Mistral AI', 'European frontier lab, funding, partnerships', 'en', 'Mistral AI is a French model company with open-weight models. This is their X account: a large funding round, partnerships with Mozilla and HUMAIN in Saudi Arabia, an enterprise control and open platform message, a security incident statement, and the AI Engineer conference in Paris. Posts are company announcements, a few per month. It does not post benchmarks or technical model details here.', null, 0.3, 208561, '["We are aware of a claim alleging unauthorized access to our systems. Following a thorough investigat","Today, we are announcing a partnership with @mozilla  to bring privacy, control and choice to people","Our open-weight models, products and infrastructure give organisations a real choice over how and wh"]')
