insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-aiatmeta', 'x_account', 'https://x.com/AIatMeta', 'AI at Meta', 'Meta''s models and agents', 'en', 'AI at Meta is Meta''s AI research and product group. This is their X account: the Muse personal agent launch powered by Muse Spark, Muse Realtime Voice and Avatar with technical details on distillation and streaming, the AIRA agent system in a Kaggle competition, and research blog links. Posts are research threads with method details, in bursts weeks apart. It does not cover Meta''s business or other companies'' models beyond ensembles it tested.', null, 0.5, 855434, '["Read our research blog to learn more about Muse Realtime Avatar: https://t.co/pVq9K0fxCG","We put Muse Realtime Avatar head-to-head with two leading commercial avatar systems in their own liv","Live video streaming needs to respond instantly while remaining visually consistent over long conver"]')
