insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-cursor_ai', 'x_account', 'https://x.com/cursor_ai', 'Cursor', 'coding agent product updates', 'en', 'Cursor is a startup that makes an AI coding agent. This is their X account: feature launches like Projects, Rollouts and Security Reviewer, model availability such as Claude Opus 5.5 with CursorBench scores and cost per task, agent harness improvements and token cost reductions, and plan-level availability. Posts are product threads with numbers. It does not post about funding or the broader industry.', null, 0.8, 484243, '["Rollouts and Security Reviewer are available today on Teams and Enterprise plans.\n\nWe’re including R","Along with Rollouts, we''ve made a major update to Security Reviewer.\n\nSecurity Reviewer now finishes","Introducing Rollouts.\n\nRollouts write a monitoring plan, then watch changes as they deploy. \n\nDeploy"]')
