insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-perplexity_ai', 'x_account', 'https://x.com/perplexity_ai', 'Perplexity', 'AI search product and API', 'en', 'Perplexity is an AI search company. This is their X account: Fast Search in the Perplexity Search API, the Photon retrieval engine with latency and cost numbers, Portable Computer, a local agent for Windows, and plan availability. Posts are product threads with benchmarks, many in one day around a launch. It does not cover funding or other companies.', null, 10, 506517, '["Inside Photon, p99 response time dropped from about 800 ms to about 65 ms. It uses about 20% fewer s","Photon builds new indexes separately from the servers handling live queries.\n\nWhen a version is read","Photon stores the index in compact formats, so each query reads and decodes only what it needs.\n\nWhe"]')
