insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-techcrunch', 'x_account', 'https://x.com/TechCrunch', 'TechCrunch', 'tech industry and startup news', 'en', 'TechCrunch is a technology news publication. This is their X account: headline links to its stories on AI labs like OpenAI and Anthropic (model drops, cloud deals, agent incidents), startup funding rounds, data center buildouts, company governance news like Automattic''s board, Meta hardware, and its Disrupt conference. Posts are one-line summaries with a link, many per day. It covers all of tech, not AI alone, and offers no first-party announcements.', null, 10, 11013028, '["The company behind Facebook and Instagram wants to keep consumers connected to the digital world via","Boom Supersonic CEO Blake Scholl said its new stationary power plants were no longer in Crusoe''s nea","After days of upheaval at Automattic, following a failed attempt to remove CEO Matt Mullenweg, the c"]')
