insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-huggingface', 'x_account', 'https://x.com/huggingface', 'Hugging Face', 'open models and community', 'en', 'Hugging Face hosts open models and the community around them. This is their X account: rare original posts on the Training Agents series, open-weight models like Inkling-Small, and open science, between many retweets and replies. Original posts arrive a few times a month. It does not cover company news, funding or the closed labs directly.', null, 0.2, 802014, '["Training Agents 4: From reward functions to environments. https://t.co/9VSrFcBiPU","🤗💚\nhttps://t.co/coHXLgzNXh https://t.co/Ju5e0R4roZ","We use Inkling-Small to turn paper abstracts into quick, useful summaries.\n\nopen weights × open scie"]')
