insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-ycombinator', 'x_account', 'https://x.com/ycombinator', 'Y Combinator', 'YC-backed startup spotlights', 'en', 'Y Combinator is a startup accelerator. This is their X account: short spotlights on companies it backs, such as Vapi''s voice agent platform and Hop Aero''s cargo rockets, with what they build and who they serve, plus link posts. Original posts sit between many replies and retweets. It does not cover the big AI labs or general industry news.', null, 3, 1652702, '["Hop Aero is building rockets that can deliver cargo anywhere on Earth in minutes.\n\nThey’re starting ","https://t.co/zmwj8aZhG6 https://t.co/nFc1RXpIOL","Vapi (@Vapi_AI) is the platform for building and deploying voice AI agents. It now serves about a bi"]')
