insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-github', 'x_account', 'https://x.com/github', 'GitHub', 'GitHub and Copilot product news', 'en', 'GitHub is the code hosting and developer platform owned by Microsoft. This is their X account: posts about the GitHub Copilot app and its agents, pull request review tooling, Dependabot automation, GitHub Advanced Security webinars, GitHub Universe conference sessions, and engineering deep dives on how the product is built. Several posts a day, all announcements and event promotion from the company itself. It does not report on other companies'' tools.', null, 5, 2714358, '["Chat, tell us: Is chat always the right UI?  @burkeholland argues no, not when we have canvases in t","You can write and ship more code than ever. But can you trust it?  On September 29, we''ll cover how ","Dependabot pull requests are easy to review one at a time ... and tedious to review by the dozen.  B"]')
