insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-vercel', 'x_account', 'https://x.com/vercel', 'Vercel', 'Vercel platform and AI Gateway', 'en', 'Vercel is the hosting and infrastructure company behind Next.js, v0 and AI Gateway. This is their X account: customer stories about internal app platforms built on Vercel, AI Gateway model adoption figures and pricing promotions, the skills.sh agent skills registry, and Fluid Compute and CDN pricing announcements. A few posts a week, all about Vercel''s own platform and the models and agents reachable through it. It does not report on the wider industry.', null, 0.4, 459693, '["Engineers @klaviyo built an internal app platform on Vercel. In the first two weeks, 512 employees s","In 7 months, the skills.⁠sh registry reached 1 million agent skills and nearly 280 million installs.","Build with Grok 4.7 and Vercel for less.  40% off until September 27th on AI Gateway. Try with @v0, "]')
