insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-cognition', 'x_account', 'https://x.com/cognition', 'Cognition', 'Devin and coding agent news', 'en', 'Cognition is the company that makes Devin, an AI software engineering agent. This is their X account: Devin product updates such as Microsoft Teams and Microsoft 365 integration, new models like GPT-6 Sol and Luna arriving in Devin with benchmark comparisons, and company milestones such as revenue run rate. Multi-post threads with ''Read more'' links to their blog, several posts a day in launch weeks. Only about Devin and Cognition, no coverage of rival agents.', null, 3.5, 185437, '["Cognition has crossed $1B in annualized revenue run rate.   This milestone belongs to our customers.","And Devin now works natively with Microsoft 365: grant access to Outlook, Calendar, OneDrive, ShareP","In Microsoft Teams, you can now direct message Devin, start a group chat, or spin up Automations fro"]')
