insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-openrouter', 'x_account', 'https://x.com/OpenRouter', 'OpenRouter', 'model routing and new model availability', 'en', 'OpenRouter is a unified API that routes requests to hundreds of language models. This is their X account: launches of routing products such as the Jev Router built on TypeSafe''s Jev model, benchmark results against its own Auto Router, and explanations of how routing, caching and data retention work. Under five posts a day averaged over the account''s whole history, with long many-post threads on a launch day (the ten newest posts were one such day''s thread). A source for which models and routers are shipping across labs, seen through OpenRouter''s catalog.', null, 4.8, 148998, '["You can see Jev Router''s thinking process in OpenRouter Chat.  The routing insights panel shows the ","If the Jev call times out or returns invalid output, the request fails instead of falling back to an","Jev Router keeps a model that works for the rest of the session.  It can raise or lower effort witho"]')
