insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-theo', 'x_account', 'https://x.com/theo', 'Theo - t3.gg', 'AI coding tool opinions', 'en', 'Theo Browne runs T3 Chat and T3 Code and makes developer videos on YouTube. This is his X account: roughly nineteen posts a day averaged over the account''s whole history, replies included (the ten newest original posts fell within one day), with blunt opinions on coding agents (Claude, Codex, Opus), usage limits and account bans, which models are popular in his products, Linux versus macOS for running agents, and screenshots and jokes about the AI developer scene. Personal takes rather than announcements, at high volume.', null, 18.6, 391965, '["I was so innocent at the time... https://t.co/H3DMw38RmN","Holy shit https://t.co/gkF1591Ylw","Vid on \"why linux\"  https://t.co/A80WPr9m3g"]')
