insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-bcherny', 'x_account', 'https://x.com/bcherny', 'Boris Cherny', 'Claude Code from the inside', 'en', 'Boris Cherny works at Anthropic on Claude Code. This is his X account: first-hand notes on Claude Code features such as Projects, how Opus 5.5 performs as a daily driver, experiments like formally verifying the Claude Agent SDK with Lean, internal agents that write pull requests, and speed improvements to the desktop app. About one post a day, almost entirely Claude and Anthropic tooling. Not a general AI news feed.', null, 1.2, 581653, '["Can’t wait to see what you build. https://t.co/IzsiejH1fa","Tag writes &gt;50% of my PRs every day. It also does ~100% of my data analysis, and fixes most of ou","It was an honor to meet Donald Knuth at the Computer History Museum today https://t.co/U6bGOidLmw"]')
