insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-steipete', 'x_account', 'https://x.com/steipete', 'Peter Steinberger 🦞', 'OpenClaw and hands-on agent building', 'en', 'Peter Steinberger is the creator of OpenClaw, an open source agent framework, and a longtime iOS developer. This is his X account: OpenClaw releases and partnerships such as Microsoft shipping a product on it, engineering lessons like sync database access mistakes, having agents delete 400k lines of tests, memory leaks found in dependencies, and reactions to the agent hype cycle. Several posts a day, mixing technical detail with jokes and photos.', null, 7.2, 592196, '["keep thinking https://t.co/m9hPGboarc","The biggest design mistake I made when we moved OC to sqlite: using sync db access. When it was just","day of the dead https://t.co/ivXMULng59"]')
