insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-linear', 'x_account', 'https://x.com/linear', 'Linear', 'Linear product and coding agent updates', 'en', 'Linear is a project and issue tracking product for software teams. This is their X account: weekly changelog items such as the Linear coding agent, adaptive model routing, environment secrets, new models available in coding sessions (GPT-6 Sol, Luna, Opus 5.5), MCP access to the inbox and mobile features. About one post a day, only about Linear''s own product.', null, 1.3, 113423, '["See everything Linear’s cloud coding agent can do and how to put it to work:  https://t.co/D9ikwDhHV","New: Secure setup for Linear coding agent    Coding sessions can now access environment secrets duri","Other coding agent improvements include environment secrets and support for open-weight models.  Lea"]')
