insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-karpathy', 'x_account', 'https://x.com/karpathy', 'Andrej Karpathy', 'LLM insights from a researcher', 'en', 'Andrej Karpathy is an AI researcher, formerly of OpenAI and Tesla. This is his X account: long, plain-language posts on how to work with LLMs (ramble sessions, asking for HTML output), ways to test models beyond the pelican drawing, reactions to model releases like Claude Fable 5, talk summaries, and occasional admiration for SpaceX. Rare, roughly a couple of posts a month, often weeks apart.', null, 0.1, 4222194, '["More on the pelican on the bicycle test from @simonw: https://t.co/OXmtODyTKj  I uploaded the source","We''re starting to leave the territory where you''d test an LLM by e.g. \"create an svg of pelican on a","One pattern I find useful for working with LLMs is a nice long ramble session. Sometimes the LLM nee"]')
