insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-verge', 'x_account', 'https://x.com/verge', 'The Verge', 'consumer tech headlines', 'en', 'The Verge is a consumer technology news site. This is their X account: roughly forty-five headlines a day averaged over the account''s whole history (the ten newest posts all fell within one day), linking to articles and the Vergecast on gadgets and deals (phones, cameras, HomePod, e-bikes), platform news from Meta, Apple and Google, AI lawsuits and agent incidents, and robotics. A consumer and culture angle on tech; developer tools appear rarely.', null, 44.9, 4694973, '["Yes, if it’s Amflow’s TL Carbon ,  but expect compromises. https://t.co/OaKzs2G1HY","We also found discounted DJI Osmo Nano bundles, the first sale on the Nothing Phone 4A Pro, and a $3","On The Vergecast: Meta Connect, Muse, Googlebooks, and more. https://t.co/rJqwJmmPtF"]')
