insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-paulg', 'x_account', 'https://x.com/paulg', 'Paul Graham', 'startup and AI essays', 'en', 'Paul Graham co-founded Y Combinator and writes essays on startups. This is his X account: observations on how people describe LLMs and what words like ''think'' mean for them, startup ideas prompted by AI problems, model bug-finding cost charts, advice to students on where to work in the AI age, plus book notes and gripes about language usage. A few posts a day, opinions and essays rather than news.', null, 3.8, 5325793, '["I''m reading Shakespeare''s Professional Career by Peter Thomson. Like most really good books, it cove","If you know anyone looking for a good and fairly AI-proof career, watchmaker (= watch repairer) seem","Using \"think\" to describe what an LLM does reminds me of the 16th century, when astronomers didn''t r"]')
