insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-heygen', 'x_account', 'https://x.com/HeyGen', 'HeyGen', 'AI avatar video tools', 'en', 'HeyGen is the company behind an AI avatar and video generation product. This is their X account: product updates such as custom avatar looks and multilingual avatar videos, integrations with agents and assistants like Muse, ChatGPT and Claude through an MCP, workflow walkthroughs, small surveys about business video, and event announcements like workshops. It does not cover AI news beyond HeyGen''s own product and partners.', null, 1, 112228, '["And don''t forget to dress for success. Custom looks let you put your avatar in any outfit without lo","New weekly update workflow Step 1: open Claude Cowork Step 2: \"read this week''s Slack and make me a ","71.6% of small business owners have filmed a video for their business and never posted it. 53.9% sai"]')
