insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-odysseyml', 'x_account', 'https://x.com/odysseyml', 'Odyssey', 'world models and simulated environments', 'en', 'Odyssey is an AI lab building world models that simulate interactive environments in real time. This is their X account: launches of its Odyssey and Agora model generations, multiplayer research previews where humans and agents share a simulated world, claims about world models controlling robots, cars and drones, and teaser posts before releases. It does not cover general AI tools or coding products.', null, 1, 42607, '["Going forward, we believe multi-agent world models will increasingly power important applications ac","This research preview of Agora-2 enables up to 4 humans to join together to battle 16 agents, in an ","Introducing Agora-2, our next-generation multi-agent world model. Agora-2 supports up to 20 humans a"]')
