insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-qoder_ai_ide', 'x_account', 'https://x.com/qoder_ai_ide', 'Qoder', 'agentic coding platform', 'en', 'Qoder is an agentic coding platform and desktop IDE from Alibaba. This is their X account: free model promotions such as Qwen models at no credit cost, daily credit packs and consumption rate changes, new team features like Projects and Discussions, and conference announcements about the product line. It does not cover other coding tools or general AI news.', null, 1.9, 11834, '["Getting started: 1. Download the Qoder desktop app. 2. Sign in and select Qwen3.8-Flash. No claim ne","Qwen3.8-Flash is free in Qoder through Sept 30. Free accounts included. No claim, no Credits. Throug","When every teammate has an Agent, how do you actually keep the team in sync? Qoder Projects &amp; Di"]')
