insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-cresta', 'x_account', 'https://x.com/cresta', 'Cresta', 'AI agents for customer support', 'en', 'Cresta sells an AI platform for contact centers and customer experience teams. This is their X account: webinars and conference sessions about AI agents in customer service, featured customer speakers such as Alaska Airlines at its own CrestaWAVE event, and customer-service takes tied to news moments. It does not cover developer tools or general AI model news.', null, 0.7, 1807, '["Are you building the wrong AI agent strategy? 🤔 In our upcoming webinar with @Metrigy, we’re debunki","✈️ Excited to have Lori Bradshaw of @AlaskaAir as a featured speaker at #CrestaWAVE 2026! We’re prou","Bad CX always strikes at the worst possible time. Even for @MoneyLynch It’s time to hit the Beast Mo"]')
