insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-n8n_io', 'x_account', 'https://x.com/n8n_io', 'n8n.io', 'AI workflow automation', 'en', 'n8n is a workflow automation tool for technical teams building AI-connected workflows. This is their X account: its own conference In The Loop with speakers and partner sessions, featured workflow templates, talks at events such as GTC and HumanX, co-hosted builder events with OpenAI, and agent permission patterns with partners like NVIDIA and Microsoft. It does not cover automation tools other than n8n.', null, 2.7, 83812, '["Great few days at @HumanXCo in Amsterdam. Thanks to everyone who stopped by the n8n booth and shared","Jamie Madden, our Senior Education DevRel at n8n, is speaking at @NVIDIAGTC Berlin this October. He’","Agentic automation only scales with identity, permissions &amp; a reusable pattern in place. Oliver "]')
