insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-rowancheung', 'x_account', 'https://x.com/rowancheung', 'Rowan Cheung', 'AI news highlights and personal workflows', 'en', 'Rowan Cheung is the founder of The Rundown AI, a daily AI newsletter. This is his X account: standout AI stories such as brain implants restoring movement or dogs detecting cancer with detailed threads and links to papers, lists of consumer products with AI integrated well or badly, and his own AI journaling and workflow setups. The account posts a few times a week rather than daily. It does not carry the full daily tool roundup, which lives in the newsletter.', null, 0.7, 597614, '["Full paper: https://t.co/dDxhuKgzLn","Surgeons implanted 5 electrode arrays in his brain An AI detects when he intends to move and stimula","AI is now helping paralyzed people move again. This man is moving his own hand with an implant train"]')
