insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-producthunt', 'x_account', 'https://x.com/ProductHunt', 'Product Hunt', 'daily new product launches', 'en', 'Product Hunt is the site where makers launch new products every day. This is their X account: many posts a day highlighting individual launches with a one-line explanation and maker handle, from AI video editors and fundraising agents to browser simulations and privacy tools, plus newsletter roundups and reposts of community reactions. Most featured products are early-stage and not yet well known. It does not cover funding news or model research.', null, 10.9, 565884, '["Pass my exam, make no mistakes https://t.co/HWnk3T85hj","Love to see it! https://t.co/BlJ32N3fyy","And of course more in the Newsletter! Subscribe here: https://t.co/05tgaMLXjL https://t.co/arWubrjK8"]')
