insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-elevenlabs', 'x_account', 'https://x.com/ElevenLabs', 'ElevenLabs', 'AI voice, speech and audio tools', 'en', 'ElevenLabs is the company behind AI voice, speech-to-text and audio generation models and the ElevenCreative, ElevenAgents and ElevenAPI products. This is their X account: model and product releases such as Scribe v2 Medical for clinical speech-to-text and Studio 4.0, its AI-native video editor, integrations with assistants like Muse, customer and partner case studies such as a voice-driven humanoid robot, and program announcements like free access for students. It does not cover AI news beyond ElevenLabs'' own products and partners.', null, 1.3, 193763, '["The easiest way to prepare students for the work they''ll do after university is to give them the too","Asking out loud is the fastest way to get almost anything done. Even if you''re asking a robot. This ","ElevenLabs is coming to @Muse. Voiceovers, soundtracks, and videos are just a message away inside Me"]')
