insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-testingcatalog', 'x_account', 'https://x.com/testingcatalog', 'TestingCatalog', 'feature sightings across AI products', 'en', 'TestingCatalog is a news account that reports unreleased and newly shipped features across AI products. This is their X account: sightings of upcoming plans and features such as a ChatGPT Pro Max tier or a new Claude Code layout in Claude Desktop, app UI changes in ChatGPT and Claude, launches like the new Copilot app modes and plugin submissions on Claude Directory, smaller tool launches, and a daily AI brief that sums up the day''s news by company. It does not cover hands-on tutorials or funding news.', null, 9.9, 77407, '["DAILY AI BRIEF 🗞, Sept 26 MICROSOFT 🔥: - Biggest Copilot update yet: Home (Chat + Cowork), Code, Aut","Anthropic is developing a new Claude Code layout for Claude Desktop, with an updated model selector ","Codex is down. This sounds like a banked reset 👀 https://t.co/Avsf0zk6Lr"]')
