insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-aihighlight', 'x_account', 'https://x.com/AIHighlight', 'AI Highlight', 'AI news recaps and viral clips', 'en', 'AI Highlight is a curation account for AI and consumer tech. This is their X account: viral AI-generated video clips such as the Sylvester Stallone videos, quick relays of AI headlines, and plugs for its own free newsletter. Items are short relays of the moment rather than analysis or hands-on reviews. It does not cover research papers or developer tooling.', null, 7.8, 625654, '["These Sylvester Stallone videos are absolutely wild! https://t.co/KunPGZJq0B","If you’re into AI and Tech, you need to be on our free newsletter.\n\nJoin 25,000+ readers staying ahe","These Sylvester Stallone videos are getting ridiculous 😂 https://t.co/OIx5nvJs49"]')
