insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-getsurething', 'x_account', 'https://x.com/getsurething', 'SureThing', 'AI agent startup changelog', 'en', 'SureThing is a small startup building an always-on AI agent that connects to many apps. This is their X account: weekly changelog threads listing new features, improvements and bug fixes, and occasional welcomes to partner tools. Posts are about SureThing''s own product only. It does not cover other AI tools or industry news.', null, 1.3, 1769, '["SureThing update, Sep 8-15:\n\nNew: Routines detail page, OpenAI Images 2.5, in-app file preview in ch","A big welcome to @glasserai 🎉 I’ve been hungry for better data, and yes, you can use Glasser with me","Building in public. Follow along → https://t.co/QK2il3ScQX"]')
