insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-boltzbit', 'x_account', 'https://x.com/boltzbit', 'Boltzbit', 'AI research lab views', 'en', 'Boltzbit is a London AI research company working on models that keep learning from live data. This is their X account: previews of its own papers, threads arguing about what AGI means and the limits of task-length benchmarks, and links to interviews with its researchers. Posting is infrequent, a few times a month. It does not cover product launches or tools from other companies.', null, 0.3, 220, '["We’ve just released the preview version of our latest paper: Infinite-Parameter LLMs - Generating an","The industry declared #AGI (again) this week. Dr @YichuanZhang_ ''s piece with @DIGIWORLD_INFO discus","The progress in task horizon is real and worth building on. The argument here isn''t against agentic "]')
