insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-midjourney', 'x_account', 'https://x.com/midjourney', 'Midjourney', 'image model release notes', 'en', 'Midjourney is an image generation research lab. This is their X account: release notes for model updates such as v8.1 with its new --tile mode for seamless patterns, a new edit model for consistent characters, weekly office hours recaps, community polls about priorities, and meetup announcements. Posting is a few times a month, clustered around releases. It does not cover other image tools or AI news.', null, 0.2, 461872, '["A lot of people are wondering how to use our new edit model for consistent characters and more - so ","A few quick updates today! We''re releasing a new version of --tile for seamless patterns in v8.1 and","Midjourney Weekly Office Hours - 9/16 https://t.co/qkX6ZaJv4X"]')
