insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-david_ornstein', 'x_account', 'https://x.com/David_Ornstein', 'David Ornstein', 'English transfer and governance exclusives', 'en', 'David Ornstein is the football correspondent of The Athletic, based in England. This is their X account: exclusive reporting on Premier League clubs, in the sampled posts the Manchester City financial-rules verdict and the clubs'' planned legal response, with some posts published as bare links to The Athletic. Posts arrived a few times a week in the sampled window. It covers English football; other leagues appear only when a story involves an English club.', null, 0.4, 4697672, '["🚨 Premier League clubs planning legal action following guilty verdict against Manchester City relati","https://t.co/ykAkD3O3Xd https://t.co/4fzFe52FpS","🚨 EXCLUSIVE: Manchester City found guilty on virtually all charges relating to breaches of Premier L"]')
