insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-fabricehawkins', 'x_account', 'https://x.com/FabriceHawkins', 'Fabrice Hawkins', 'France national team and French players', 'fr', 'Fabrice Hawkins is a French football journalist reporting for RMC Sport. This is their X account: the France national team under Zidane (lineups, call-ups, players leaving the camp) and injury news on French players such as Mbappé and Koundé, written in French. It covers French football and French players wherever they play; club news arrives through those players rather than as club coverage.', null, 1.9, 284744, '["🚨🇫🇷 Kylian Mbappé va quitter le rassemblement de l’équipe de France après sa blessure au genou lors ","La première composition d’équipe de Zinédine Zidane pour Turquie - France : Maignan – Koundé, Lacroi","https://t.co/5mB7wGnnse"]')
