insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-mariocortegana', 'x_account', 'https://x.com/MarioCortegana', 'Mario Cortegana', 'Real Madrid and Spanish market', 'en', 'Mario Cortegana covers Real Madrid for The Athletic. This is their X account: inside reporting on Real Madrid''s first team and dressing room (the mood after the derby defeat, midfield control), Mbappé injury updates, and short cryptic posts or links, in English and Spanish. It covers Real Madrid only, with other clubs appearing as opponents.', null, 0.8, 284741, '["JMTR. https://t.co/q0RIfzHScH","Real Madrid’s Kylian Mbappe to return to Spain for scan on knee injury sustained in France victory @","⚡️Inside Real Madrid post derby defeat: ➕Lack of control in midfield &amp; attitude ➕“The problem wi"]')
