insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-monfortcarlos', 'x_account', 'https://x.com/monfortcarlos', 'Carlos Monfort', 'Barcelona first team daily news', 'es', 'Carlos Monfort is a journalist at the Barcelona sports daily SPORT. This is their X account: daily FC Barcelona news in Spanish, with injury recoveries (De Jong, Casadó), training schedules under Flick, goalkeeper selection, youth signings and renewals (Iker Rodríguez, Dany Freire), and contract talks such as Raphinha''s renewal, linking to SPORT. It also carries club commercial and media stories like the Clásico shirt sponsor. It covers FC Barcelona only, with other clubs appearing as opponents or as the other side of a deal.', null, 2, 69307, '["❗️Marc Casadó, en la Ciutat Esportiva para recuperarse de su lesión. El centrocampista catalán, cedi","❗️Contamos en @sport De Jong mejora sensaciones y da un paso adelante en su recuperación. El neerlan","ℹ️ Hoy Flick ha dado fiesta a los no internacionales. Los lesionados han ido a recuperarse de sus re"]')
