insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-catalunyaradio', 'x_account', 'https://x.com/CatalunyaRadio', 'Catalunya Ràdio', 'Catalan public radio, general news', 'ca', 'Catalunya Ràdio is the official account of Catalonia''s national public radio station. This is their X account: clips and links from its programmes in Catalan on politics, culture, books, housing, theatre and daily life in Catalonia, ten or more posts a day. FC Barcelona appears only occasionally through clips from its Barça programme, such as a piece on the team''s physical preparation. It is a general news and culture account rather than a sports one; its sports shows post from their own accounts (@totcosta on weekdays, @ClubMitjanit on Sundays).', null, 10, 303572, '["\"Traduir llibres és com tenir un fill.\" Durant La Setmana del Llibre en Català descobrim la feina qu","Portada @rogerescapa: \"La Maricarmen ha deixat amb el cul a l''aire totes les costures del sistema\" #","El Teatre Lliure celebra 50 anys i, per això, Magí Camps, Marta Orriols i Marta Vives s''han colat a "]')
