insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-fcbarcelona', 'x_account', 'https://x.com/FCBarcelona', 'FC Barcelona', 'Official club channel', 'en', 'FC Barcelona is the official English-language X account of the club. This is their X account: international duty check-ins on its players during national-team breaks, La Liga highlight clips, membership and VIP seating announcements, fan polls and sponsor content such as eFootball, posted around nine times a day. It gives the club''s own view: official announcements and highlights, not reporting or rumours about the squad.', null, 9, 46895387, '["Too good not to recreate. 🎮 @play_eFootball https://t.co/Ny4u8gpXFY","🌍 International duty check-in: Hamza Abdelkarim played in the second half for Egypt in their goalles","🌍 International duty check-in: Jules Kounde played the full 90 minutes in France’s Nations League wi"]')
