insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-diarioas', 'x_account', 'https://x.com/diarioas', 'Diario AS', 'Spanish sports daily, Madrid-leaning', 'es', 'Diario AS is a Madrid-based Spanish sports newspaper. This is their X account: breaking news in Spanish on Real Madrid and the Spain national team, Mbappé''s injury, the daily front page, Nations League and youth World Cup coverage, quizzes and photo galleries, ten or more posts a day. It is a general Spanish sports daily with a Madrid lean, covering every sport the paper follows.', null, 10, 3241864, '["🌟🌟 ABRAN PASO AL CAMPEÓN 🇪🇸🏴󠁧󠁢󠁥󠁮󠁧󠁿 España estrenará las DOS ESTRELLAS en Wembley frente a Inglaterra","✨📰 ¡Ya está aquí la #PortadAS del sábado, 26 de septiembre! 🌟🌟 Estreno mundial https://t.co/oYu6Krgl","🚨 ¡Mbappé abandona Francia y regresa a Madrid para recibir tratamiento! 🇫🇷❌ Zidane transmitió preocu"]')
