insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-esport3', 'x_account', 'https://x.com/esport3', 'Esport3', 'Catalan sports TV, all sports', 'ca', 'Esport3 is the sports channel of Catalan public broadcaster TV3 and Catalunya Ràdio. This is their X account: sports news in Catalan on football (Manchester City''s verdict, Mbappé''s injury, Girona, Barça futsal), cycling and other sports, with links to its site, ten or more posts a day. It is broad Catalan sports news across every sport rather than one club or league.', null, 10, 203723, '["🤦‍♂️ ES PASSA DE VELOCITAT ❌ Expulsen al seleccionador espanyol junior de ciclisme del Mundial per c","❗👀 Declaren el Manchester City culpable de 114 irregularitats financeres de les 115 acusacions contr","❌🏥 Kylian Mbappé abandona la concentració de França per una lesió tendinosa al genoll esquerre 🚨 El "]')
