insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-gerardromero', 'x_account', 'https://x.com/gerardromero', 'Gerard Romero', 'Barcelona talk shows and Jijantes', 'es', 'Gerard Romero is a Catalan sports commentator who runs the Jijantes streaming channel and its Kings League team. This is their X account: links to Jijantes shows and debates about FC Barcelona (Flick''s team, Raphinha), short reactions to Real Madrid and Mourinho, and jokes and memes during international breaks, in Spanish. The posts point to the shows on @JijantesFC rather than carrying reports themselves; it is a show-promotion feed, not a structured news feed.', null, 4.7, 1396951, '["🎥Con @JaqueMarquez7 a las 22h valoración del inicio de temporada @JijantesFC https://t.co/0nC1x1Jf9P","Sigue el show en la Castellana… https://t.co/QWfBg2dvcq","Sigue el show en la Castellana… https://t.co/JTqEgx8yzp"]')
