insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-plettigoal', 'x_account', 'https://x.com/Plettigoal', 'Florian Plettenberg', 'German transfers and Bundesliga', 'en', 'Florian Plettenberg is a Sky Sport Germany reporter covering transfers and the Germany national team. This is their X account: Bundesliga coaching changes (Hannover, Mönchengladbach, Ingolstadt), quotes from managers and done-deal announcements, in English and German. It covers German football first: Bundesliga clubs, German players abroad and the national team.', null, 1.4, 846859, '["🚨❌ Sabrina #Wittmann has been relieved of her duties at FC Ingolstadt. Decision has been made. Wittm","🚨🆕 Borussia Mönchengladbach are in advanced negotiations with Alexander Blessin. Verbal agreement is","🚨💥 Sandro Wagner to Hannover 96 - DONE DEAL ✔️ Full agreement reached. Contract until 2028. Wagner t"]')
