insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-realmadrid', 'x_account', 'https://x.com/realmadrid', 'Real Madrid C.F.', 'Real Madrid official channel', 'es', 'Real Madrid C.F. is the club''s official Spanish-language X account. This is their X account: scorelines and player mentions from its internationals on national duty, awards for its players, medical reports, merchandise and video-game partnerships, posted several times a day in Spanish. It covers Real Madrid only, with other clubs appearing as opponents.', null, 6.5, 49536738, '["🇹🇷 0-1 🇫🇷 ⚽ @KMbappe 👉 @Camavinga 👉 @10ArdaGuler 🏆 Liga de Naciones https://t.co/CQ3WoqJ8MI","🔝 ¡@BellinghamJude, elegido mejor jugador de la selección inglesa de la temporada 2025/26! https://t","🇦🇺 1-1 🇧🇷 👉 @ViniJr 👉 @Endrick 🤝 Amistoso https://t.co/fJE1eXd9yl"]')
