insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-fcbfemeni', 'x_account', 'https://x.com/FCBfemeni', 'FC Barcelona Femení', 'Barcelona women''s team official', 'ca', 'FC Barcelona Femení is the official account of the club''s women''s team. This is their X account: matchday build-up, squad lists, travel and training photos, coach Pere Romeu''s press conferences and ticket links, in Catalan, ten or more posts a day. It covers the women''s team only.', null, 10, 1213189, '["✨ 𝗨𝗡 𝗗𝗜𝗔 𝗗𝗘 𝗣𝗔𝗥𝗧𝗜𝗧 ✨ #LogroñoUnitedBarça https://t.co/LLkxiOlMts","Viatge ✔️ https://t.co/yE5Kw2ZXAq","🔜 Dos partits a l''Spotify Camp Nou! Aprofita aquesta oportunitat! 🎟️👇 https://t.co/hkFm8Elfdx https:"]')
