insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-premierleague', 'x_account', 'https://x.com/premierleague', 'Premier League', 'Premier League official channel', 'en', 'The Premier League is the league''s official X account. This is their X account: highlight clips of goals and moments from English top-flight matches, player milestone posts, quizzes, sponsor votes and fantasy promotions, posted around nine times a day in English. It covers the Premier League''s own clubs and players only, as highlights and promotion rather than news reporting.', null, 9, 46246173, '["Jeremy Jacquet was born for the big stage 💪 https://t.co/v3yV4lLcfK","That Jurgen Klopp passion 🤩 https://t.co/6CnGGPcTFQ","Even this Sunderland fan had to appreciate Bruno Guimaraes'' strike 😮‍💨 https://t.co/PkVUX5wd46"]')
