insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-theathleticfc', 'x_account', 'https://x.com/TheAthleticFC', 'The Athletic | Football', 'English football news desk', 'en', 'The Athletic | Football is the football desk of The Athletic. This is their X account: article and video links on English football, currently dominated by the Manchester City financial-rules verdict and its fallout, plus interview series and Premier League club news, posted several times a day in English. It is an English-football news desk; other leagues appear occasionally through its correspondents.', null, 9, 1271646, '["Manchester City have been found guilty of 114 of 115 charges in relation to the Premier League''s fin","What does Manchester City''s guilty verdict mean for Pep Guardiola? @mjshrimper and @SamLee discuss G","Which Spice Girl would @GNev2 have married? Welcome to Truth or Padel, the new limited series where "]')
