insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-spacexai', 'x_account', 'https://x.com/SpaceXAI', 'SpaceXAI', 'xAI''s Grok model and API releases', 'en', 'SpaceXAI is the account where xAI announces its Grok models. This is their X account: Grok model releases such as Grok 4.7 with availability in Cursor, Grok Build and the Grok API and a comparison against Grok 4.6, Grok Voice launches like Transcribe 2.0 with per-hour prices, customer examples with Atlassian''s Loom and fal, and an apology after an outage at its Memphis compute center. Posts arrive as threads of three or four on a launch day, then a gap of days. It does not post about SpaceX rockets, funding or other labs'' models.', null, 0.6, 2068031, '["Grok 4.7 is available now in Cursor and Grok Build, and the Grok API.\n\nLearn more: https://t.co/GybE","Grok 4.7 is here.\n\nIt''s a notable improvement over Grok 4.6 at the same price and speed. https://t.c","Introducing Grok Voice Transcribe 2.0. It’s the world’s most accurate speech transcription model. ht"]')
on conflict (id) do update set name = excluded.name, focus = excluded.focus, lang = excluded.lang, description = excluded.description, items_per_week = excluded.items_per_week, posts_per_day = excluded.posts_per_day, followers = excluded.followers, recent_titles = excluded.recent_titles;

insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-nvidia', 'x_account', 'https://x.com/nvidia', 'NVIDIA', 'NVIDIA partnerships, Jensen Huang, AI infrastructure', 'en', 'NVIDIA is the chip company whose GPUs run most AI training and inference. This is their X account: research partnerships such as open protein complex structures for 2,800 viruses with Google DeepMind and EMBL-EBI, Jensen Huang at the G20 innovation ministerial and on The Ezra Klein Show with figures like a gigawatt AI factory costing 50 to 60 billion dollars, enterprise AI conversations with partners like VAST Data, and stories about companies using NVIDIA AI in clean energy and nuclear. Posts are threads with a story link, several a day. It does not post chip specifications, earnings or prices here, and it does not cover other companies'' models.', null, 3.7, 2671117, '["With @GoogleDeepMind, @emblebi, and research partners, we’re making AI-predicted protein complex str","At the G20 Innovation Ministerial, @JensenHuang joined U.S. Commerce Secretary @howardlutnick to dis","From fusion energy to repurposed EV batteries, five companies are using NVIDIA AI, digital twins and"]')
on conflict (id) do update set name = excluded.name, focus = excluded.focus, lang = excluded.lang, description = excluded.description, items_per_week = excluded.items_per_week, posts_per_day = excluded.posts_per_day, followers = excluded.followers, recent_titles = excluded.recent_titles;

insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-a16z', 'x_account', 'https://x.com/a16z', 'a16z', 'Andreessen Horowitz launches and partner clips', 'en', 'a16z is the venture firm Andreessen Horowitz. This is their X account: the launch of Cosign, its professional network for startup people, told through clips of partners Erik Torenberg, David Booth, Olivia Moore and Ben Horowitz on how one introduction or endorsement leads to hires, deals and companies, plus podcast clips such as Ben Horowitz on Lenny''s Podcast. Posts are quotes and short videos, ten or more posts a day around a launch. The ten newest posts are all about Cosign; none are deal announcements, portfolio funding news or model comparisons.', null, 10, 1079377, '["Announcing Cosign.\n\nSilicon Valley knows people by watching other people know them. One person''s vis","Who believed in you first? Silicon Valley runs on that question.\n\na16z''s Erik Torenberg, David Booth","Ben Horowitz cosigned the Databricks co-founders in 2013, when they were Berkeley academics.\n\n\" When"]')
on conflict (id) do update set name = excluded.name, focus = excluded.focus, lang = excluded.lang, description = excluded.description, items_per_week = excluded.items_per_week, posts_per_day = excluded.posts_per_day, followers = excluded.followers, recent_titles = excluded.recent_titles;

insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-simonw', 'x_account', 'https://x.com/simonw', 'Simon Willison', 'hands-on model and tool evaluation', 'en', 'Simon Willison is the creator of Datasette, a co-creator of Django and the author of a daily blog on AI tools. This is his X account: same-day write-ups of model releases such as Claude Opus 5.5 and GPT-6 Sol and Luna with price comparisons and his pelican drawing tests, notes on new model categories like TypeSafe''s Jev decision models, small tools he builds such as a Gemini TTS playground and a Datasette MCP that talks to ChatGPT, and reflections on what coding agents do to software engineering, plus conference keynotes. One or two posts a day, most linking to his blog. Hands-on evaluation and cost notes rather than company announcements or funding news.', null, 1.5, 226300, '["Big model release today - I wrote about Claude Opus 5.5, GPT-6 Sol, and GPT-6 Luna - plus comparison","Put together some notes on Jev and the new category of system one aka decision models https://t.co/E","The more time I spend working with coding agents, the more convinced I am that they make software en"]')
