insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-sama', 'x_account', 'https://x.com/sama', 'Sam Altman', 'OpenAI from its CEO', 'en', 'Sam Altman is the CEO of OpenAI. This is his X account: launch-day threads on OpenAI''s own models such as GPT-6 Sol and Luna with their per-token and per-task pricing against the 5.6 family, notes ahead of DevDay and on the OpenAI API roadmap across text, code, image and video, praise for OpenAI staff, and statements on the company''s review of how its agents used internet access during training. Around three posts a day in a launch week, clustered on announcement days and informal in tone. It covers OpenAI''s side only, with no commentary on other labs'' releases.', null, 3.3, 6284508, '["GPT-6 Sol and Luna are big improvements on intelligence, alignment, work output, coding, computer us","We want the OpenAI API to feature the best model at every price point and to be the best at every mo","There is an extensive and ongoing review related to our agents’ use of internet access during traini"]')
