insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-therundownai', 'x_account', 'https://x.com/TheRundownAI', 'The Rundown AI', 'daily AI news digest', 'en', 'The Rundown AI is the account of the daily AI newsletter founded by Rowan Cheung. This is their X account: one "Top stories in AI today" post each morning listing that day''s four headlines, such as Meta Connect, Claude Opus 5.5, the GPT-6 Sol and Luna release and a16z''s college alternative, with a read-more link, plus same-day posts on frontier model releases and a how-to tip like using Gemini Canvas with Google Sheets. Coverage is a news digest across the big labs and consumer AI products rather than hands-on reviews. It does not cover small indie tools or Product Hunt launches.', null, 3.5, 228986, '["Read more: https://t.co/E0ZvWU9rrK","Top stories in AI today:\n\n- Meta’s Connect turns into a Muse takeover\n- Rowan’s Corner: The Rundown ","Read more: https://t.co/7cPxdbYo9T"]')
