insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-sport', 'x_account', 'https://x.com/sport', 'Diario SPORT', 'Barcelona sports daily, all sports', 'es', 'Diario SPORT is a Barcelona-based Spanish sports newspaper. This is their X account: article links in Spanish on FC Barcelona (Balde''s possible January exit with Juventus, Liverpool and Manchester United interested, Flick pairing Rodri and Bernal, a Confidencial piece on Carlos Bianchi), signed opinion columns tagged OPINIÓN SPORT on Raphinha, Mbappé and the international break, Mbappé''s medical report, the daily front page, Barça basketball and tennis such as Alcaraz at the Laver Cup, ten or more posts a day. It is a general sports daily with a strong Barcelona lean, covering every sport the paper follows rather than one club.', null, 10, 2003235, '["‼️ El exespanyolista Osvaldo, en estado muy grave ✍️ @Clauespi8 https://t.co/P3PGS2flDR","CONFIDENCIAL SPORT 🔴 📄 El informe inédito que recomendaba a Carlos Bianchi para el Barça: \"Michels m","💼 Movimiento para la salida de Balde del Barça en enero 👉 La Juventus se suma al interés de Liverpoo"]')
