insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-jijantesfc', 'x_account', 'https://x.com/JijantesFC', 'Jijantes FC', 'Barcelona streaming shows and interviews', 'es', 'Jijantes FC is the official account of the Jijantes streaming channel, which broadcasts daily football shows from Barcelona. This is their X account: clips and quotes from its live shows in Spanish, mostly about FC Barcelona (Deco on Julián Álvarez, Gerard Martín on competition in the squad, a former club physio on Lamine Yamal''s workload and the international break, the VIP boxes at the Spotify Camp Nou), plus segments on the Spain national team and a daily YouTube recap, ten or more posts a day. It carries show excerpts and links to the stream rather than written reports; other clubs appear only as talking points on the shows.', null, 10, 325840, '["👀 Recupera lo más destacado del día en el FORMATÍN de YouTube ‼️ https://t.co/CWS9zD331y","📺 DIRECTO @JijantesFC Gerard Martín: \"Sé lo que estoy haciendo y de lo que soy capaz. En un equipo s","📺 DIRECTO @JijantesFC 💰🏟️ Charlamos con @aPartidoUnico de la notícia del día: la comercialización de"]')
