insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-fcbarcelona_es', 'x_account', 'https://x.com/FCBarcelona_es', 'FC Barcelona', 'Official club channel in Spanish', 'es', 'FC Barcelona is the club''s official Spanish-language X account, the Spanish counterpart of its English one. This is their X account: check-ins on its players on international duty (Koundé with France, Raphinha with Brazil, Bernal and Espart with Spain under-21), La Liga highlight clips, a monthly best-moment poll, VIP seat sales at the Spotify Camp Nou, ticket links and sponsor content such as eFootball, posted around eight times a day in Spanish. It gives the club''s own view: official announcements and highlights, not reporting or rumours about the squad.', null, 7.7, 20158071, '["Demasiado bueno como para no recrearlo @play_eFootball 🎮🔥 https://t.co/tdbokuoknE","🌍 Nuestros internacionales: Hamza Abdelkarim ha participado en la segunda parte con Egipto en el emp","🌍 Nuestros internacionales: Jules Kounde ha jugado los 90 minutos en la victoria de Francia ante Tur"]')
on conflict (id) do update set name = excluded.name, focus = excluded.focus, lang = excluded.lang, description = excluded.description, items_per_week = excluded.items_per_week, posts_per_day = excluded.posts_per_day, followers = excluded.followers, recent_titles = excluded.recent_titles;

insert into public.sources (id, kind, target, name, focus, lang, description, items_per_week, posts_per_day, followers, recent_titles)
values ('x-totcosta', 'x_account', 'https://x.com/totcosta', 'Tot costa', 'Catalan radio sports show, Barcelona-heavy', 'ca', 'Tot costa is the weekday evening sports programme of Catalunya Ràdio, on air from 7 to 9 pm. This is their X account: audio clips and links from each show in Catalan, mostly on FC Barcelona (Deco closing the door on Julián Álvarez, 2,000 more VIP seats going on sale, a Camp Nou bid for the 2030 World Cup final discussed with the Catalan government''s sports minister), interviews with Barça women''s players, Girona match broadcasts and a listener guessing game about players, ten or more posts a day while the show is on. It covers Catalan sport with Barcelona at the centre, and posts cluster around the show''s weekday evening slot.', null, 10, 40736, '["🏟️ Les opcions del Camp Nou de ser l''estadi escollit per ser seu de la final del Mundial 2030. En pa","🔊 Generació de fills de futbolistes als Països Baixos La Caçatalents, amb Andrea Orts https://t.co/b","🎙️ És possible la final del Mundial 2030 al Camp Nou? Ho respon @b5alvarez, Conseller d''Esports de l"]')
